      "sonar_vision": "Sonar Vision",
      "sonar_vision_hearing_as_imaging": "Sonar Vision — hearing as imaging",
      "sonar_vision_simulator_use_arrow_keys_": "Sonar vision simulator. Use arrow keys or WASD to move the bat. Press Space to emit a sonar pulse. Objects illuminate briefly when hit by sound waves.",
      "sound_in_the_real_world_technology_ins": "Sound in the Real World — Technology Inspired by Nature",
      "sound_intensity_decreases_with_the_squ": "Sound intensity decreases with the square of distance. Double the distance = quarter the intensity.",
      "sound_map": "Sound Map",
      "sound_moves_slowly_through_air_because": "Sound moves slowly through air because air molecules are far apart. Speed increases ~0.6 m/s per °C rise in temperature.",
      "sound_waves": "Sound Waves",
      "sound_waves_wavelength_meets_target_si": "Sound Waves — wavelength meets target size",
      "soundscape": "Soundscape",
      "space_emit_sonar_pulse": "SPACE: Emit sonar pulse",
